globalThis.ops=[
"Can Caldrian utilities finance their 2027 capex plans through debt markets?",
"Can Caldrian utilities finance their 2027 capex plans through equity markets?"].map(t=>nodes.open({task:t}));
const r=await Promise.all(ops.map(o=>o.result()));
return r.map(x=>read(x.ref));

// Judgments already split into n2,n3,n4 (demand, financing, pricing). Wait for them.
const out=[];let r;
for(let i=0;i<30;i++){r=await nodes.next();out.push(...r.lines);if(["n2","n3","n4"].every(n=>out.some(l=>l.startsWith(n+".r"))))break;}
return out.join("\n");
